import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2 } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  const group = new THREE.Group();
  group.userData.handlers = {};
  group.userData.cleanup = () => {
    group.traverse((child) => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) {
        if (Array.isArray(child.material)) {
          child.material.forEach((m) => m.dispose());
        } else {
          child.material.dispose();
        }
      }
    });
  };

  // Atlas dimensions and region
  const atlasWidth = 512;
  const atlasHeight = 320;
  const regionX = 0;
  const regionY = 0;
  const regionWidth = 512;
  const regionHeight = 320;

  // Calculate aspect ratio for plane geometry
  const aspectRatio = regionWidth / regionHeight;
  const planeHeight = 1.2;
  const planeWidth = planeHeight * aspectRatio;

  // Create plane geometry
  const geometry = new THREE.PlaneGeometry(planeWidth, planeHeight, 1, 1);

  // Load texture and create material
  ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
    texture.magFilter = THREE.LinearFilter;
    texture.minFilter = THREE.LinearMipmapLinearFilter;

    // Create UV offset node for atlas region
    const atlasUV = uv()
      .mul(vec2(regionWidth / atlasWidth, regionHeight / atlasHeight))
      .add(vec2(regionX / atlasWidth, regionY / atlasHeight));

    // Create material with atlas-mapped texture
    const material = new MeshBasicNodeMaterial({
      map: texture,
      transparent: true,
      depthTest: true,
      depthWrite: false,
      side: THREE.DoubleSide,
    });

    // Manually override the UV in the material
    material.colorNode = texture.uv(atlasUV);

    const mesh = new THREE.Mesh(geometry, material);
    mesh.castShadow = false;
    mesh.receiveShadow = false;

    group.add(mesh);
  });

  // Render text content from config
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const textObj = ctx.fontAtlas.createText(String(item.text || ''), {
      fontSize: item.typography?.fontSize ?? 39,
      color: '#e8ecf2',
      align: 'center',
    });
    textObj.position.set(0, -planeHeight * 0.5 - 0.35, 0.1);
    group.add(textObj);
  }

  return group;
}
